package com.eec.bookhub.controller;
import com.eec.bookhub.model.*;import com.eec.bookhub.repository.NotificationRepository;import com.eec.bookhub.service.CurrentUserService;import jakarta.servlet.http.HttpSession;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notifications")
public class NotificationController {private final NotificationRepository repo;private final CurrentUserService current;public NotificationController(NotificationRepository repo,CurrentUserService current){this.repo=repo;this.current=current;}
@GetMapping public List<Notification> all(HttpSession s){User u=current.require(s);return repo.findByUserIdOrderByDateDesc(u.id);} @PostMapping("/{id}/read") public Map<String,Object> read(@PathVariable String id,HttpSession s){User u=current.require(s);Notification n=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Notification not found."));if(!n.userId.equals(u.id))throw new SecurityException("Not allowed.");n.read=true;repo.save(n);return Map.of("ok",true);} @PostMapping("/read-all") public Map<String,Object> allRead(HttpSession s){User u=current.require(s);var list=repo.findByUserIdOrderByDateDesc(u.id);list.forEach(n->n.read=true);repo.saveAll(list);return Map.of("ok",true);} }
